      {
        "factor": "Lamag's large victory margin and unity-government support in Sabah",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "A 5,681-vote majority and unity-government context reduce overturn incentives absent new evidence."
      },
      {
        "factor": "Concurrent by-elections context and time window for petitions",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Time window to May 1, 2026 is short; petitions would need rapid court action to overturn, which is unlikely."
      }
